// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public {
        c = new MyContract();
        vm.deal(address(c), 1 ether);
    }

    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        // Admissible domain: any amount strictly greater than c's balance.
        amount = bound(amount, address(c).balance + 1, type(uint128).max);

        address owner = address(this);
        vm.deal(owner, 0);
        vm.prank(owner);
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Rule: sending more ether than c holds must fail.
        assertTrue(!ok);
    }
}
